import CoreGraphics
import Foundation
import Testing
@testable import Layer

// The structure fixtures (`LayerTests/Fixtures/structure-*.json`, generated by `Tools/SketchBenchmarkHarness`) in the
// simulator: each batch of sketches is read by the rules, placed with `SketchedNode` on a free screen, and the structure
// pass runs over it. The macOS harness's `structure` mode runs the same fixtures through the same code.

private final class BundleMarker {}

private struct Found {
    var fixture: StructureFixture
    var label: String
    var decision: String
    var seconds: Double
}

@Suite("Structure fixtures")
struct StructureFixtureTests {
    private static let fixtures: [StructureFixture] = {
        guard let directory = Bundle(for: BundleMarker.self).resourceURL,
              let loaded = try? StructureBenchmark.load(from: directory)
        else { return [] }
        return loaded
    }()

    private static func run(_ fixtures: [StructureFixture]) -> [Found] {
        fixtures.map { fixture in
            let found = StructureBenchmark.run(fixture)
            return Found(fixture: fixture, label: found.label, decision: found.decision, seconds: found.passSeconds)
        }
    }

    @Test func theStructureFixturesLoaded() throws {
        #expect(Self.fixtures.count == 32)
        #expect(Dictionary(grouping: Self.fixtures, by: \.variant).mapValues(\.count)
            == [.clean: 9, .jittered: 8, .noisy: 7, .nearMiss: 8])
        #expect(Dictionary(grouping: Self.fixtures.filter { $0.variant != .nearMiss }, by: \.label).mapValues(\.count)
            == ["row": 8, "column": 6, "grid": 6, "card": 4])
        // The sketch corpus is untouched, and still doesn't see these.
        let directory = try #require(Bundle(for: BundleMarker.self).resourceURL)
        #expect(try SketchFixtureCorpus.load(from: directory).count == 156)
    }

    @Test func cleanAndJitteredFixturesBecomeTheirStructure() {
        let drawn = Self.run(Self.fixtures.filter { $0.variant == .clean || $0.variant == .jittered })
        #expect(drawn.count == 17)
        let wrong = drawn.filter { $0.label != $0.fixture.label || $0.decision != $0.fixture.expected }
        #expect(wrong.isEmpty, "\(wrong.map { "\($0.fixture.id): \($0.label) \($0.decision)" })")
    }

    @Test func nearMissesNeverGroup() {
        let misses = Self.run(Self.fixtures.filter { $0.variant == .nearMiss })
        #expect(misses.count == 8)
        let grouped = misses.filter { $0.label != "none" || $0.decision != "none" }
        #expect(grouped.isEmpty, "\(grouped.map { "\($0.fixture.id): \($0.label) \($0.decision)" })")
    }

    @Test func noisyFixturesAreNeverTheWrongStructure() {
        let noisy = Self.run(Self.fixtures.filter { $0.variant == .noisy })
        #expect(noisy.count == 7)
        let wrong = noisy.filter { $0.label != $0.fixture.label && $0.label != "none" }
        #expect(wrong.isEmpty, "\(wrong.map { "\($0.fixture.id): \($0.label) \($0.decision)" })")
    }

    @Test func printsTheStructureReport() {
        let found = Self.run(Self.fixtures)
        let asExpected = found.filter { $0.fixture.isAsExpected(label: $0.label, decision: $0.decision) }
        let grouped = found.filter { $0.fixture.variant == .nearMiss && $0.label != "none" }
        let times = found.map(\.seconds).sorted()
        func percentile(_ fraction: Double) -> Double {
            guard !times.isEmpty else { return 0 }
            return times[min(times.count - 1, max(0, Int((Double(times.count) * fraction).rounded(.up)) - 1))]
        }
        print("=== Structure benchmark (Simulator) ===")
        print("structure: \(found.count) fixtures, \(asExpected.count) as expected, near misses grouped \(grouped.count)")
        for kind in ["row", "column", "grid", "card", "none"] {
            let ofKind = found.filter { $0.label == kind }
            print("  found \(kind): \(ofKind.count) (\(ofKind.filter { $0.decision == "apply" }.count) applied, "
                + "\(ofKind.filter { $0.decision == "offer" }.count) offered)")
        }
        print("Pass p50/p95: \(String(format: "%.4f", percentile(0.5) * 1000))ms / \(String(format: "%.4f", percentile(0.95) * 1000))ms")
        #expect(found.count == 32)
        #expect(asExpected.count == 32)
        #expect(grouped.isEmpty)
    }
}
